-- Re-runnable: on conflict (id) do nothing.

insert into public.questions
  (id, topic, difficulty, prompt, options, answer, explanation, sign_code,
   topic_tag, exam_likelihood, vehicle_codes, in_exam, in_readiness,
   source_basis, review_status, sort_order)
values
  ('RR-001', 'rules', 1, 'Unless a road sign shows otherwise, what is the general speed limit on a public road in an urban area?', '["60 km/h","40 km/h","80 km/h"]'::jsonb, 0, 'The default urban speed limit in South Africa is 60 km/h. 40 km/h and 80 km/h are not the general urban default; a posted sign could set a different limit, but absent one the limit is 60.', null, 'Speed Limits', 'high', '{"A","B","C","EB"}', true, false, 'legislation', 'approved', 1),
  ('RR-002', 'rules', 1, 'What is the general maximum speed limit for a light motor vehicle on a freeway, where no lower limit is posted?', '["100 km/h","120 km/h","140 km/h"]'::jsonb, 1, 'The general freeway limit is 120 km/h. 100 km/h is the default for a non-freeway rural public road, and 140 km/h is not a legal South African limit.', null, 'Speed Limits', 'high', '{"A","B","C","EB"}', true, false, 'legislation', 'approved', 2),
  ('RR-003', 'rules', 2, 'A goods vehicle with a gross vehicle mass over 9 000 kg is travelling on a freeway. What is the maximum speed it may legally travel?', '["100 km/h","120 km/h","80 km/h"]'::jsonb, 2, 'A goods vehicle over 9 000 kg GVM is capped at 80 km/h even on a freeway, regardless of the 120 km/h general limit. The other options ignore the class-specific cap.', null, 'Speed Limits', 'medium', '{"C"}', true, false, 'legislation', 'approved', 3),
  ('RR-004', 'rules', 2, 'In good conditions, what is the safest way to judge a following distance behind the vehicle ahead?', '["Keep a time gap of at least two seconds","Stay exactly 50 metres behind at all times","Keep one car length behind regardless of speed"]'::jsonb, 0, 'A time-based gap (the two-second rule) is correct because the safe distance grows automatically with speed. A fixed metre distance or ''one car length'' does not scale with speed and is unsafe at higher speeds.', null, 'Following Distance', 'high', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 4),
  ('RR-005', 'rules', 2, 'Two vehicles reach a four-way stop and stop at exactly the same moment. Who has the right of way?', '["The larger or heavier vehicle","The vehicle on the right","The vehicle going straight ahead"]'::jsonb, 1, 'When two vehicles stop together at a four-way stop, the vehicle on the right proceeds first. Vehicle size and direction of travel do not determine priority — there is no main road at a four-way stop.', null, 'Right of Way', 'high', '{"A","B","C","EB"}', true, false, 'legislation', 'approved', 5),
  ('RR-006', 'rules', 1, 'What must you do when you approach a yield sign and the road you are joining is completely clear?', '["Come to a complete stop before proceeding","Sound your hooter and drive through","Slow down and proceed without stopping if it is safe"]'::jsonb, 2, 'A yield sign requires you to give way only if necessary; if the way is clear you may proceed without stopping. A complete stop is required at a stop sign, not a yield sign.', 'R2', 'Right of Way', 'high', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 6),
  ('RR-007', 'rules', 2, 'What is the maximum legal blood-alcohol concentration for an ordinary (non-professional) driver in South Africa?', '["Below 0.05 g per 100 ml","Below 0.02 g per 100 ml","Below 0.08 g per 100 ml"]'::jsonb, 0, 'The ordinary-driver limit is below 0.05 g/100 ml. 0.02 applies to professional drivers, and 0.08 is the United States limit, not South Africa''s.', null, 'Alcohol Limit', 'high', '{"A","B","C","EB"}', true, false, 'legislation', 'approved', 7),
  ('RR-008', 'rules', 3, 'How close to a pedestrian crossing, on the approach side, may you NOT stop your vehicle?', '["Within 5 metres","Within 9 metres","Within 20 metres"]'::jsonb, 1, 'You may not stop within 9 metres on the approach to a pedestrian crossing. The 5-metre figure applies to parking near an intersection, a common point of confusion.', null, 'Stopping and Parking', 'medium', '{"A","B","C","EB"}', true, false, 'legislation', 'approved', 8),
  ('RR-009', 'rules', 3, 'Within what distance of an intersection may you NOT park in an urban area?', '["9 metres","1.5 metres","5 metres"]'::jsonb, 2, 'You may not park within 5 metres of an intersection. 9 metres is the no-stopping distance before a pedestrian crossing, and 1.5 metres is the no-parking distance from a fire hydrant.', null, 'Stopping and Parking', 'medium', '{"A","B","C","EB"}', true, false, 'legislation', 'approved', 9),
  ('RR-010', 'rules', 1, 'Who must wear a seatbelt in a private car fitted with belts in all seats?', '["Every occupant, front and back","Only the driver","Only the front-seat occupants"]'::jsonb, 0, 'Every occupant of a seat fitted with a seatbelt must wear it. Limiting it to the driver or front seats is incorrect; the driver is also legally responsible for child passengers.', null, 'Seatbelt Rule', 'high', '{"A","B","C","EB"}', true, false, 'legislation', 'approved', 10),
  ('RR-011', 'rules', 1, 'An ambulance approaches from behind with its siren on. What should you do?', '["Speed up to stay ahead of it","Give it immediate right of way, moving left and stopping if needed","Maintain your speed and ignore it until it passes"]'::jsonb, 1, 'Emergency vehicles must be given immediate and absolute right of way — move to the left and stop if necessary. Speeding up or ignoring it obstructs an emergency response and is unlawful.', null, 'Emergency Vehicles and Accidents', 'medium', '{"A","B","C","EB"}', true, false, 'legislation', 'approved', 11),
  ('RR-012', 'rules', 2, 'After a collision that damaged another vehicle but injured no one, and you did not give your details to an officer at the scene, when must you report it?', '["Only if the other driver asks you to","There is no need to report a damage-only accident","To the police within 24 hours"]'::jsonb, 2, 'You must report an accident — including damage-only accidents — to the police within 24 hours if you did not give your details to an officer at the scene. Damage-only accidents are not exempt from reporting.', null, 'Emergency Vehicles and Accidents', 'medium', '{"A","B","C","EB"}', true, false, 'legislation', 'approved', 12),
  ('RR-013', 'rules', 2, 'Apart from between sunset and sunrise, when else must your headlights be switched on?', '["When persons or vehicles are not clearly visible at 150 metres","Only when another vehicle flashes you","Only inside tunnels"]'::jsonb, 0, 'Headlights must also be on whenever visibility drops so that persons or vehicles are not clearly visible at 150 metres — for example in fog or heavy rain. Waiting to be flashed or limiting it to tunnels is incorrect.', null, 'Vehicle Lights', 'medium', '{"A","B","C","EB"}', true, false, 'legislation', 'approved', 13),
  ('RR-014', 'rules', 3, 'There is a solid white line on your side of the road and a broken line on the oncoming side. May you overtake?', '["Yes, because there is a broken line on the road","No, you may not cross the solid line on your side","Yes, but only at night"]'::jsonb, 1, 'You obey the line nearest you. A solid line on your side is a no-crossing barrier, so you may not overtake — the broken line on the far side permits the oncoming traffic to cross, not you.', null, 'Overtaking', 'high', '{"A","B","C","EB"}', true, false, 'legislation', 'approved', 14),
  ('RR-015', 'rules', 1, 'A pedestrian is crossing on your half of the roadway at a pedestrian crossing. What must you do?', '["Sound your hooter so they hurry","Drive around behind them","Yield and let the pedestrian cross"]'::jsonb, 2, 'At a pedestrian crossing you must yield to a pedestrian on your half of the road. Hooting at or driving around a pedestrian on a crossing is unlawful and unsafe.', null, 'Pedestrian Right of Way', 'high', '{"A","B","C","EB"}', true, false, 'legislation', 'approved', 15),
  ('RR-016', 'rules', 2, 'A vehicle ahead of you has stopped at a pedestrian crossing. What may you NOT do?', '["Overtake the stopped vehicle","Wait behind it until it moves off","Check for pedestrians"]'::jsonb, 0, 'You may not overtake a vehicle that has stopped at a pedestrian crossing — a pedestrian you cannot see may be crossing in front of it. Waiting and checking for pedestrians are correct.', null, 'Pedestrian Right of Way', 'medium', '{"A","B","C","EB"}', true, false, 'legislation', 'approved', 16),
  ('RR-017', 'rules', 2, 'Your indicators have failed. How do you signal a right turn by hand?', '["Right forearm pointing down","Right arm extended straight out, horizontal","Right forearm pointing up"]'::jsonb, 1, 'A right-turn hand signal is the right arm extended straight out horizontally. Forearm down signals a left turn; forearm up signals slowing or stopping.', null, 'Turning and Signals', 'medium', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 17),
  ('RR-018', 'rules', 2, 'Which hand signal indicates that you intend to slow down or stop?', '["Right arm straight out horizontally","Right forearm pointing down","Right arm out, forearm pointing up, palm forward"]'::jsonb, 2, 'The slow-down/stop hand signal is the right arm out with the forearm pointing up, palm forward. Straight out means a right turn; forearm down means a left turn.', null, 'Turning and Signals', 'medium', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 18),
  ('RR-019', 'rules', 1, 'You have just passed your learner''s licence test. May you now drive alone on a public road?', '["No, you must always be supervised by a licensed driver","Yes, the learner''s licence lets you drive alone","Yes, but only during the day"]'::jsonb, 0, 'A learner''s licence does not permit driving alone — you must always be accompanied by a licensed driver and display L plates. The learner''s licence is not a full driving licence.', null, 'Driver Documents and Roadworthiness', 'high', '{"A","B","C","EB"}', true, false, 'legislation', 'approved', 19),
  ('RR-020', 'rules', 2, 'What is the legal minimum tyre tread depth across the breadth of a tyre?', '["5 mm","1 mm","10 mm"]'::jsonb, 1, 'The legal minimum tread is 1 mm across the breadth and around the full circumference. Below this the tyre is unroadworthy. 5 mm and 10 mm are well above the legal minimum.', null, 'Driver Documents and Roadworthiness', 'medium', '{"A","B","C","EB"}', true, false, 'legislation', 'approved', 20),
  ('RR-021', 'rules', 1, 'You normally keep a two-second following gap. What should you do when it is raining heavily?', '["Keep the same two-second gap","Halve the gap to keep up","At least double the time gap"]'::jsonb, 2, 'In rain or poor grip you should at least double the time gap (three to four seconds or more), because stopping distances lengthen on a wet road. Keeping or halving the gap is unsafe.', null, 'Following Distance', 'high', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 21),
  ('RR-022', 'rules', 2, 'You are approaching a traffic circle. Who has right of way?', '["Traffic already in the circle / approaching from your right","Whoever is the largest vehicle","You, because you are entering"]'::jsonb, 0, 'At a traffic circle you yield to traffic already circulating and approaching from your right. Vehicle size gives no priority, and an entering driver must give way, not take it.', null, 'Right of Way', 'high', '{"A","B","C","EB"}', true, false, 'legislation', 'approved', 22),
  ('RR-023', 'rules', 2, 'May you overtake when approaching the summit of a rise where you cannot see oncoming traffic?', '["Yes, if you are quick","No, overtaking is prohibited where visibility is restricted","Yes, if you sound your hooter"]'::jsonb, 1, 'Overtaking is prohibited approaching a rise, curve or any place where your view of oncoming traffic is restricted. Speed or hooting does not make it legal or safe.', null, 'Overtaking', 'high', '{"A","B","C","EB"}', true, false, 'legislation', 'approved', 23),
  ('RR-024', 'rules', 2, 'What is the maximum speed limit for a minibus or bus, even on a freeway?', '["120 km/h","140 km/h","100 km/h"]'::jsonb, 2, 'Buses and minibuses are capped at 100 km/h, below the 120 km/h general freeway limit. 140 km/h is not a legal South African limit.', null, 'Speed Limits', 'medium', '{"A","B","C","EB"}', true, false, 'legislation', 'approved', 24),
  ('RR-025', 'rules', 2, 'What is the maximum legal blood-alcohol concentration for a professional (PrDP) driver?', '["Below 0.02 g per 100 ml","Below 0.05 g per 100 ml","Below 0.08 g per 100 ml"]'::jsonb, 0, 'Professional drivers face the stricter limit of below 0.02 g/100 ml. 0.05 is the ordinary-driver limit and 0.08 is the United States limit.', null, 'Alcohol Limit', 'medium', '{"A","B","C","EB"}', true, false, 'legislation', 'approved', 25),
  ('RR-026', 'rules', 3, 'How close to a fire hydrant may you NOT park?', '["Within 5 metres","Within 1.5 metres on either side","Within 9 metres"]'::jsonb, 1, 'You may not park within 1.5 metres either side of a fire hydrant. 5 metres is the no-parking distance from an intersection and 9 metres is the no-stopping distance before a pedestrian crossing.', null, 'Stopping and Parking', 'low', '{"A","B","C","EB"}', true, false, 'legislation', 'approved', 26),
  ('RR-027', 'rules', 1, 'What is the general speed limit on a public road outside an urban area that is not a freeway?', '["60 km/h","120 km/h","100 km/h"]'::jsonb, 2, 'The default limit on a non-freeway rural public road is 100 km/h. 60 is the urban default and 120 is the freeway limit.', null, 'Speed Limits', 'high', '{"A","B","C","EB"}', true, false, 'legislation', 'approved', 27),
  ('RR-028', 'rules', 2, 'Your braking (stopping) distance becomes longer when:', '["The road is wet, your speed is higher, or the vehicle is loaded","Only when it is dark","Only when the tyres are new"]'::jsonb, 0, 'Stopping distance increases on a wet road, at higher speed and when the vehicle is laden — all three. Darkness and new tyres are not the primary factors.', null, 'Following Distance', 'medium', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 28),
  ('RR-029', 'rules', 2, 'A child under the age of three is travelling in a private car. How must the child be secured?', '["On an adult''s lap with the adult belted","In an appropriate child restraint (car seat)","With an ordinary adult seatbelt"]'::jsonb, 1, 'A child under three must be secured in an appropriate child restraint. An adult''s lap is not a legal restraint, and an adult belt does not fit a child under three safely.', null, 'Seatbelt Rule', 'medium', '{"A","B","C","EB"}', true, false, 'legislation', 'approved', 29),
  ('RR-030', 'rules', 3, 'In which situation may you lawfully pass another vehicle on its left?', '["Never — you must always pass on the right","Whenever the left lane is empty on the open road","When the vehicle ahead is signalling and turning right"]'::jsonb, 2, 'You may pass on the left when the vehicle ahead is signalling and turning right (also in a one-way street or in multi-lane traffic in your direction). ''Never'' is wrong, and casually undertaking on the open road is not permitted.', null, 'Overtaking', 'medium', '{"A","B","C","EB"}', true, false, 'legislation', 'approved', 30),
  ('RR-031', 'rules', 2, 'An ordinary driver''s breath-alcohol concentration must be below which limit?', '["0.24 mg per 1 000 ml","0.50 mg per 1 000 ml","0.80 mg per 1 000 ml"]'::jsonb, 0, 'The ordinary-driver breath limit is below 0.24 mg per 1 000 ml. The other figures are not the legal breath limit; professional drivers face a stricter 0.10.', null, 'Alcohol Limit', 'medium', '{"A","B","C","EB"}', true, false, 'legislation', 'approved', 31),
  ('RR-032', 'rules', 2, 'You are following closely behind another vehicle at night. What should your headlights be on?', '["Bright (main) beam to see further","Dipped (low) beam so you do not dazzle the driver ahead","Switched off to save the battery"]'::jsonb, 1, 'Use dipped beam when following closely so you do not dazzle the driver ahead via their mirrors. Main beam dazzles, and driving without lights at night is unlawful and dangerous.', null, 'Vehicle Lights', 'medium', '{"A","B","C","EB"}', true, false, 'legislation', 'approved', 32),
  ('RR-033', 'rules', 1, 'What must every vehicle do on arriving at a four-way stop?', '["Slow down and proceed if clear","Yield only to vehicles on the main road","Come to a complete stop, then go in order of arrival"]'::jsonb, 2, 'Every vehicle must come to a complete stop, then proceed in order of arrival (first to stop, first to go; if two stop together, the one on the right goes). There is no main road at a four-way stop.', null, 'Right of Way', 'high', '{"A","B","C","EB"}', true, false, 'legislation', 'approved', 33),
  ('RR-034', 'rules', 2, 'After an accident, to whom must you give your name, address and vehicle details?', '["To anyone with reasonable grounds to ask, e.g. the other driver","Only to the police, never to other people","To nobody — it is private information"]'::jsonb, 0, 'You must give your details to anyone with reasonable grounds for requiring them, such as the other driver or an injured party, and report to police within 24 hours if you did not give details to an officer at the scene.', null, 'Emergency Vehicles and Accidents', 'medium', '{"A","B","C","EB"}', true, false, 'legislation', 'approved', 34),
  ('RR-035', 'rules', 3, 'You want to tow a trailer with a gross mass over 750 kg behind a light motor vehicle. Which licence code do you need?', '["Code A","Code EB","Code C"]'::jsonb, 1, 'Towing a trailer over 750 kg behind a light motor vehicle requires Code EB. Code A is for motorcycles and Code C is for heavy vehicles over 3 500 kg.', null, 'Driver Documents and Roadworthiness', 'low', '{"EB"}', true, false, 'legislation', 'approved', 35),
  ('RR-036', 'rules', 2, 'It is an offence to drive while under the influence of:', '["Alcohol only","Prescription medicine can never be an offence","Alcohol or any drug having a narcotic effect"]'::jsonb, 2, 'Section 65 makes it an offence to drive under the influence of alcohol OR any drug having a narcotic effect — including some prescription medicines that impair driving. It is not limited to alcohol.', null, 'Alcohol Limit', 'low', '{"A","B","C","EB"}', true, false, 'legislation', 'approved', 36),
  ('RS-001', 'signs', 1, 'You approach a red octagonal sign with the word STOP. What must you do?', '["Come to a complete stop, then proceed when safe","Slow down and proceed if the way looks clear","Stop only if other vehicles are present"]'::jsonb, 0, 'A stop sign requires a complete stop every time, then proceeding when safe — regardless of whether other traffic is present. Slowing or rolling through is a common error confused with the yield sign.', 'R1', 'Regulatory Signs', 'high', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 1),
  ('RS-002', 'signs', 1, 'A solid red circle with a single white horizontal bar means:', '["One-way traffic ahead","No entry — do not pass this point","No overtaking"]'::jsonb, 1, 'The red circle with a white bar is the no-entry sign; you may not proceed past it. It is distinct from a one-way sign (which shows the permitted direction) and a no-overtaking sign.', 'R3', 'Regulatory Signs', 'high', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 2),
  ('RS-003', 'signs', 2, 'A blue circular sign showing the number 60 in white means:', '["Maximum speed 60 km/h","Recommended speed 60 km/h","Minimum speed 60 km/h — do not drive slower"]'::jsonb, 2, 'A blue command circle sets a minimum speed: you must not drive slower than 60. A red-bordered white circle would set a maximum. Blue means ''you must''; a red border means ''you must not''.', null, 'Regulatory Signs', 'medium', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 3),
  ('RS-004', 'signs', 1, 'A white circular sign with a red border and a black ''80'' means:', '["You may not exceed 80 km/h","You must travel at least 80 km/h","Average speed should be 80 km/h"]'::jsonb, 0, 'A red-bordered white circle with a number sets the maximum speed — you may not exceed 80. Driving slower is allowed. A minimum-speed sign would be blue.', 'R201-80', 'Regulatory Signs', 'high', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 4),
  ('RS-005', 'signs', 2, 'What shape and border identify a permanent warning sign in South Africa?', '["A yellow diamond","A red-bordered triangle (apex up)","A blue circle"]'::jsonb, 1, 'Permanent warning signs are red-bordered triangles. The yellow diamond is reserved for temporary/roadworks warnings — a frequent confusion. A blue circle is a regulatory command sign.', null, 'Warning Signs', 'high', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 5),
  ('RS-006', 'signs', 1, 'A red-bordered triangle showing two children means:', '["A school zone where you must stop","A pedestrian crossing for adults only","Children may be present — reduce speed and stay alert"]'::jsonb, 2, 'The children warning calls for reduced speed and heightened alertness because children may enter the road. It is a warning, not a command to stop, and is not limited to adults.', 'W308', 'Warning Signs', 'medium', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 6),
  ('RS-007', 'signs', 2, 'A red-bordered triangle showing a car with wavy skid lines warns that:', '["The road may be slippery — reduce speed and avoid harsh inputs","There is loose gravel ahead","The road is closed"]'::jsonb, 0, 'The skid symbol warns of a slippery surface; respond by slowing and avoiding harsh braking or steering. It does not mean loose gravel or a road closure.', 'W333', 'Warning Signs', 'medium', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 7),
  ('RS-008', 'signs', 1, 'A red-bordered triangle with three arrows forming a circle tells you that:', '["You must drive in a circle","A roundabout is ahead — yield to traffic already in it","No U-turns are allowed"]'::jsonb, 1, 'This warns of a roundabout ahead, where you yield to traffic already circulating. It is not an instruction to drive in circles, nor a U-turn prohibition.', 'W201', 'Warning Signs', 'medium', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 8),
  ('RS-009', 'signs', 2, 'What is the difference between a ''no stopping'' sign and a ''no parking'' sign?', '["They mean the same thing","Under ''no stopping'' you may park but not load","Under ''no parking'' you may stop briefly to load; under ''no stopping'' you may not stop at all"]'::jsonb, 2, 'No parking permits a brief stop to load or set down passengers; no stopping forbids stopping entirely except in an emergency. They are not the same, and no stopping never permits parking.', 'R217', 'Regulatory Signs', 'medium', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 9),
  ('RS-010', 'signs', 2, 'A traffic light is showing a flashing red signal. What must you do?', '["Treat it like a stop sign — stop, then proceed when safe","Drive through, as the signal is faulty","Speed up to clear the intersection"]'::jsonb, 0, 'A flashing red signal is treated like a stop sign: stop fully, then proceed when safe. It is not a malfunction to ignore, and speeding through is dangerous and unlawful.', null, 'Traffic Signals', 'high', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 10),
  ('RS-011', 'signs', 1, 'A steady amber (yellow) traffic light means:', '["Speed up to beat the red","Prepare to stop; stop if you can do so safely","Proceed with right of way over all traffic"]'::jsonb, 1, 'Amber means prepare to stop and stop if it is safe to do so — not accelerate to beat the red. It is the single most-misunderstood signal.', null, 'Traffic Signals', 'high', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 11),
  ('RS-012', 'signs', 2, 'A single solid white line running along the centre of the road on your side means:', '["You may cross it to overtake when safe","It only marks the road edge","It is a barrier line — do not cross or straddle it"]'::jsonb, 2, 'A solid line on your side is a no-crossing barrier line. A broken line, by contrast, may be crossed when safe. It is not merely an edge marker.', null, 'Road Markings', 'high', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 12),
  ('RS-013', 'signs', 2, 'A red-bordered triangle showing a walking person means:', '["A pedestrian crossing is ahead — be ready to stop","This is a pedestrian crossing — you must stop","Pedestrians are prohibited"]'::jsonb, 0, 'The triangular sign warns that a pedestrian crossing is ahead; slow and be ready to stop. The blue rectangular sign marks the crossing itself. It does not prohibit pedestrians.', 'W306', 'Warning Signs', 'medium', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 13),
  ('RS-014', 'signs', 1, 'You are warned of a railway level crossing ahead. What must you never do?', '["Look both ways before crossing","Stop or queue with your vehicle on the tracks","Slow down on the approach"]'::jsonb, 1, 'You must never stop or queue on the railway tracks. Looking both ways and slowing down are correct behaviours on the approach.', null, 'Warning Signs', 'medium', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 14),
  ('RS-015', 'signs', 2, 'A blue circle with an arrow angling left around an obstruction means:', '["Turn left at the next intersection","Left lane closed","Pass to the left of the island or obstruction"]'::jsonb, 2, 'The keep-left command directs you to pass to the left of the marked island or obstruction. It is a positioning instruction, not a turn instruction or a lane closure.', null, 'Regulatory Signs', 'low', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 15),
  ('RS-016', 'signs', 1, 'A blue rectangular sign with a single white arrow indicates:', '["Traffic flows in the arrow''s direction only","No entry for heavy vehicles","A dead-end road"]'::jsonb, 0, 'The one-way sign shows the single permitted direction of travel; no opposing traffic should be expected. It is not a heavy-vehicle restriction or a dead-end marker.', null, 'Regulatory Signs', 'medium', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 16),
  ('RS-017', 'signs', 1, 'What does a large green sign with white place names, arrows and yellow route numbers tell you?', '["You must turn at the next exit","It gives directions to routes and destinations ahead","It is a speed-limit sign"]'::jsonb, 1, 'A green direction sign is a guidance sign giving routes and destinations ahead of a junction. It carries no command, and it is not a speed-limit sign.', null, 'Guidance and Information Signs', 'medium', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 17),
  ('RS-018', 'signs', 1, 'What is the background colour of a sign directing you to a tourist attraction?', '["Red","Green","Brown"]'::jsonb, 2, 'Tourism signs use a brown background with white text. Red borders denote prohibition, and green denotes freeway/rural direction — neither is used for tourism.', null, 'Road Sign Colour Code', 'low', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 18),
  ('RS-019', 'signs', 2, 'What shape is an information sign in South Africa?', '["Rectangular","Triangular","Circular"]'::jsonb, 0, 'Information signs are rectangular — never circular or triangular. A circle would be regulatory and a triangle would be a warning sign.', null, 'Guidance and Information Signs', 'medium', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 19),
  ('RS-020', 'signs', 3, 'You see a rectangular sign showing the letter ''P''. What does it indicate?', '["You must stop and park here","Parking is available (information) — a round/regulatory P would control it","No parking is allowed"]'::jsonb, 1, 'A rectangular ''P'' is an information sign telling you parking is available. A regulatory parking sign (which controls or reserves parking) is a different sign class — shape disambiguates. It does not compel you to park, nor does it forbid parking.', null, 'Guidance and Information Signs', 'medium', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 20),
  ('RS-021', 'signs', 1, 'A sign showing the letter ''H'' means:', '["Heavy vehicles only","A hazard ahead","A hospital / emergency medical services are ahead"]'::jsonb, 2, 'The ''H'' service symbol indicates a hospital or emergency medical services ahead. It is informational, not a heavy-vehicle restriction or a hazard warning.', null, 'Guidance and Information Signs', 'low', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 21),
  ('RS-022', 'signs', 2, 'On a freeway you pass rectangular signs showing three bars, then two, then one. What do they mean?', '["A countdown of the distance to the next exit (300 m, 200 m, 100 m)","The number of lanes ahead","A speed reducing in steps"]'::jsonb, 0, 'Countdown markers show three, two and one diagonal bars at 300, 200 and 100 metres before a freeway exit, so you can prepare to leave at speed. They are not lane counts or a stepped speed limit.', null, 'Guidance and Information Signs', 'low', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 22),
  ('RS-023', 'signs', 1, 'A red-bordered triangle showing an inverted T means:', '["A pedestrian crossing ahead","The road ends ahead — you must turn left or right","A T-shaped building ahead"]'::jsonb, 1, 'The inverted-T warning means your road terminates at a T-junction and you must turn. It is not a pedestrian or building sign, and you cannot continue straight.', 'W104', 'Warning Signs', 'medium', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 23),
  ('RS-024', 'signs', 2, 'A triangle showing two vertical arrows, one up and one down, warns that:', '["It is a one-way road ahead","You must keep left","The road becomes two-way — expect oncoming traffic"]'::jsonb, 2, 'Opposed up/down arrows warn that a one-way section becomes two-way, so expect oncoming traffic. It is not a one-way or keep-left sign.', 'W212', 'Warning Signs', 'medium', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 24),
  ('RS-025', 'signs', 1, 'A triangle with edges angling inward warns that:', '["The road narrows ahead","The road ends ahead","Lanes merge into a one-way street"]'::jsonb, 0, 'Inward-angling edges warn the carriageway narrows ahead; slow and adjust position. It does not mean the road ends or becomes one-way.', 'W328', 'Warning Signs', 'low', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 25),
  ('RS-026', 'signs', 2, 'You see a warning sign for a steep descent. What is the safest action?', '["Coast in neutral to save fuel","Select a lower gear before descending","Keep the clutch pressed down the hill"]'::jsonb, 1, 'On a steep descent select a lower gear so engine braking helps control speed and saves the brakes. Coasting in neutral or riding the clutch removes engine braking and is dangerous.', 'W322', 'Warning Signs', 'medium', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 26),
  ('RS-027', 'signs', 3, 'Which sign shows a car with curved skid marks behind its wheels?', '["The gravel-road-begins sign","The loose-stones sign","The slippery-road sign"]'::jsonb, 2, 'The skidding-car symbol is the slippery-road sign. The gravel-begins sign shows tar ending and gravel starting; loose-stones shows a wheel throwing up stones. The test exploits this three-way confusion.', 'W333', 'Warning Signs', 'medium', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 27),
  ('RS-028', 'signs', 1, 'A triangle showing a raised rounded-mound profile warns of:', '["Speed humps ahead","An uneven, potholed road","A narrow bridge"]'::jsonb, 0, 'The rounded-mound profile warns of speed humps; slow enough to cross safely. The jagged profile is uneven roadway, and a bridge sign shows pinching parapets.', 'W332', 'Warning Signs', 'low', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 28),
  ('RS-029', 'signs', 2, 'A triangle showing a leaping buck warns of:', '["Domestic cattle on the road","Wild animals (game) that may cross","A hunting area where you must stop"]'::jsonb, 1, 'The leaping-buck symbol warns of wild game crossing. A cattle silhouette would be the domestic-animals sign. It is a warning, not a command to stop.', 'W313', 'Warning Signs', 'low', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 29),
  ('RS-030', 'signs', 2, 'A round white sign with a red ring and a left arrow crossed by a red slash means:', '["You must turn left","Left lane for buses only","You may not turn left"]'::jsonb, 2, 'A red ring and slash make it a prohibition: you may not turn left. A blue circle with a white left arrow would command the turn instead. Colour signals the meaning.', null, 'Regulatory Signs', 'medium', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 30),
  ('RS-031', 'signs', 3, 'A round prohibition sign with two vertical arrows pointing toward each other and ''4,4 m'' means:', '["Vehicles taller than 4.4 m may not pass","Vehicles wider than 4.4 m may not pass","Minimum height 4.4 m to pass"]'::jsonb, 0, 'Vertical arrows indicate a height limit — vehicles taller than 4.4 m are prohibited. Horizontal arrows would indicate a width limit. It is a maximum, not a minimum.', 'R204', 'Regulatory Signs', 'medium', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 31),
  ('RS-032', 'signs', 2, 'A round prohibition sign with two horizontal arrows pointing toward each other and a measurement means:', '["A height limit","A width limit — wider vehicles prohibited","A following-distance instruction"]'::jsonb, 1, 'Horizontal arrows indicate a width limit; vehicles wider than the stated measurement are prohibited. Vertical arrows would be a height limit.', null, 'Regulatory Signs', 'low', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 32),
  ('RS-033', 'signs', 1, 'A round white sign with a red ring and a truck symbol means:', '["All vehicles are prohibited","A truck stop is ahead","Goods/heavy vehicles are prohibited"]'::jsonb, 2, 'The red-ringed truck prohibits goods/heavy vehicles; light vehicles are unaffected. It does not ban all traffic, nor does it indicate a truck stop.', null, 'Regulatory Signs', 'low', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 33),
  ('RS-034', 'signs', 2, 'A blue circle with three white arrows forming a clockwise loop tells you to:', '["Yield to traffic in the circle and proceed clockwise","Make a U-turn","Stop completely before entering"]'::jsonb, 0, 'The blue roundabout command directs you to circulate clockwise, yielding to traffic already in the circle and from your right. It is not a U-turn or an automatic full-stop sign.', 'R137', 'Regulatory Signs', 'medium', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 34),
  ('RS-035', 'signs', 1, 'A blue circle with a white arrow curving left means:', '["You may not turn left","You must turn left ahead","Left lane closed"]'::jsonb, 1, 'A blue circle is a command: you must turn left. The red-ringed version would prohibit the turn. Blue means ''you must''; a red border means ''you must not''.', null, 'Regulatory Signs', 'medium', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 35),
  ('RS-036', 'signs', 2, 'You see a yellow diamond-shaped sign at roadworks. What does the yellow background tell you?', '["The sign is permanent and may be ignored","The sign is advisory only and need not be obeyed","The sign is temporary and overrides the permanent signs"]'::jsonb, 2, 'A yellow background marks the sign as temporary (roadworks) and means it overrides the normal permanent signs. Temporary signs must still be obeyed.', null, 'Road Sign Colour Code', 'medium', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 36),
  ('RS-037', 'signs', 1, 'At roadworks a worker holds a board showing a red STOP face toward you. What must you do?', '["Stop and wait until the GO face is shown","Proceed slowly past the worker","Sound your hooter and continue"]'::jsonb, 0, 'A Stop/Go board controls a single open lane through the works — on the red STOP face you must stop and wait until the green GO face is shown. Proceeding risks a head-on collision in the works zone.', 'R1.5', 'Road Sign Colour Code', 'medium', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 37),
  ('RS-038', 'signs', 2, 'A broken white line is painted along the centre of the road on your side. What does it allow?', '["You may never cross it","You may cross it to overtake when it is safe","It marks a no-stopping zone"]'::jsonb, 1, 'A broken line may be crossed to overtake or change lanes when it is safe. A solid line on your side is the no-crossing barrier. It is not a no-stopping marking.', null, 'Road Markings', 'high', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 38),
  ('RS-039', 'signs', 2, 'A row of painted white triangles across your lane at a junction means:', '["Stop completely behind the line","Pedestrian crossing ahead","Yield (give way) — stop only if necessary"]'::jsonb, 2, 'A row of triangles is a give-way (yield) line: slow and yield, stopping only if needed. A solid stop line means a complete stop; zebra stripes mark a pedestrian crossing.', null, 'Road Markings', 'medium', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 39),
  ('RS-040', 'signs', 1, 'A round white sign with a red ring and a U-shaped arrow crossed by a red slash means:', '["You may not make a U-turn here","You must make a U-turn","No right turn"]'::jsonb, 0, 'The red-slashed U-arrow prohibits a U-turn at this point. It does not command a U-turn, and it is distinct from a no-right-turn sign.', 'R213', 'Regulatory Signs', 'medium', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 40),
  ('RS-041', 'signs', 2, 'A blue rectangular sign showing a pedestrian on zebra stripes means:', '["Pedestrians are prohibited here","This is a pedestrian crossing — give way to pedestrians on it","A pedestrian crossing is somewhere ahead"]'::jsonb, 1, 'The blue command sign marks the actual pedestrian crossing and requires you to give way to pedestrians on it. The triangular warning sign means a crossing is ahead; this blue sign is the crossing itself.', null, 'Regulatory Signs', 'medium', '{"A","B","C","EB"}', false, false, 'official_manual', 'draft', 41),
  ('RS-042', 'signs', 1, 'At a railway crossing the boom is down and the red lights are flashing. What must you do?', '["Drive around the boom if no train is visible","Sound your hooter and cross quickly","Stop and wait until the boom lifts and the lights stop"]'::jsonb, 2, 'You must stop and wait until the boom lifts and the lights stop — a train is approaching. Driving around a boom is extremely dangerous and unlawful.', null, 'Warning Signs', 'medium', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 42),
  ('VC-001', 'controls', 1, 'Which control would you use to stop the vehicle quickly in an emergency?', '["The foot (service) brake","The handbrake","The clutch"]'::jsonb, 0, 'The foot/service brake is used to slow or stop, including emergency stops. The handbrake only keeps a stationary vehicle still, and the clutch disengages the engine — neither stops the vehicle safely.', null, 'Vehicle Controls', 'high', '{"B"}', true, false, 'official_manual', 'approved', 1),
  ('VC-002', 'controls', 1, 'Which control keeps the vehicle stationary after you have parked it?', '["The accelerator","The hand (parking) brake","The clutch"]'::jsonb, 1, 'The handbrake/parking brake holds a parked vehicle in place. The accelerator increases speed and the clutch disengages the gearbox — neither holds the vehicle still.', null, 'Vehicle Controls', 'high', '{"B"}', true, false, 'official_manual', 'approved', 2),
  ('VC-003', 'controls', 1, 'Which control regulates the fuel supply to the engine to increase the vehicle''s speed?', '["The brake","The gear lever","The accelerator"]'::jsonb, 2, 'The accelerator regulates fuel to the engine to increase speed. The brake slows the vehicle and the gear lever selects the ratio — they do not increase speed directly.', null, 'Vehicle Controls', 'high', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 3),
  ('VC-004', 'controls', 2, 'Which statement about the clutch is correct?', '["An automatic vehicle does not have a clutch control","Every vehicle, including automatics, has a clutch control","The clutch is used to stop the vehicle in an emergency"]'::jsonb, 0, 'Automatic vehicles do not have a clutch control. The clutch is used to change gear on a manual, not to perform an emergency stop (that is the foot brake).', null, 'Vehicle Controls', 'medium', '{"B"}', true, false, 'official_manual', 'approved', 4),
  ('VC-005', 'controls', 2, 'On a manual vehicle, which two controls do you use together to change gear?', '["The accelerator and the brake","The clutch and the gear lever","The handbrake and the steering wheel"]'::jsonb, 1, 'Changing gear on a manual uses the clutch and the gear lever together. The other pairs perform unrelated functions.', null, 'Vehicle Controls', 'medium', '{"B"}', true, false, 'official_manual', 'approved', 5),
  ('VC-006', 'controls', 1, 'Before changing direction, changing speed or braking, what should a driver always do first?', '["Sound the hooter","Switch on the hazard lights","Check the mirrors"]'::jsonb, 2, 'The manual''s standing rule is to check the mirrors first, before any change of speed, direction or braking. The hooter and hazard lights serve different, situational purposes.', null, 'Vehicle Controls', 'high', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 6),
  ('VC-007', 'controls', 1, 'Which control advises other road users of your intention to turn?', '["The direction indicators","The steering wheel","The accelerator"]'::jsonb, 0, 'The direction indicators signal your intention to turn or change direction. The steering wheel changes direction but does not signal it, and the accelerator controls speed.', null, 'Vehicle Controls', 'high', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 7),
  ('VC-008', 'controls', 1, 'Your windscreen has rain on the outside obscuring your view. Which control do you use?', '["The demister","The windscreen wipers","The hazard lights"]'::jsonb, 1, 'The windscreen wipers clear rain and dirt from the outside of the glass. The demister clears misting on the inside, and hazard lights do not affect visibility through the windscreen.', null, 'Vehicle Controls', 'medium', '{"B"}', true, false, 'official_manual', 'approved', 8),
  ('VC-009', 'controls', 1, 'The inside of your windscreen has misted up on a cold morning. Which control clears it?', '["The windscreen wipers","The horn","The demister"]'::jsonb, 2, 'The demister clears condensation from the inside of the glass. The wipers clear the outside, and the horn is a warning device.', null, 'Vehicle Controls', 'low', '{"B"}', true, false, 'generated_from_syllabus', 'approved', 9),
  ('VC-010', 'controls', 2, 'On a motorcycle, how do you bring the machine to a controlled stop?', '["Use the front brake lever and the rear brake pedal together","Use the front brake lever only","Use the clutch lever only"]'::jsonb, 0, 'A motorcycle is stopped using the front brake lever and rear brake pedal in combination for balanced, controlled braking. Using one brake alone or the clutch is incorrect.', null, 'Vehicle Controls', 'medium', '{"A"}', true, false, 'official_manual', 'approved', 10),
  ('VC-011', 'controls', 2, 'How should you use the brake during an emergency stop in a vehicle fitted with ABS?', '["Pump the brake pedal rapidly","Apply firm, continuous pressure and keep steering","Use the handbrake instead"]'::jsonb, 1, 'With ABS you apply firm, continuous pressure and hold it — the system prevents wheel lock so you keep steering control. Pumping defeats ABS, and the handbrake is not for emergency stops.', null, 'Vehicle Controls', 'medium', '{"B"}', true, false, 'official_manual', 'approved', 11),
  ('VC-012', 'controls', 2, 'How should a head restraint (headrest) be positioned?', '["As low as possible for comfort","Removed when not needed","With its top roughly level with the top of your head"]'::jsonb, 2, 'The head restraint should have its top roughly level with the top of your head to limit rearward head movement and reduce whiplash in a rear-end crash. Set too low or removed, it offers little protection.', null, 'Vehicle Controls', 'low', '{"B"}', true, false, 'official_manual', 'approved', 12),
  ('VC-013', 'controls', 1, 'When is it appropriate to switch on your hazard lights?', '["When your vehicle is stationary in a hazardous position or broken down","When driving normally in heavy rain","To justify parking in a no-stopping zone"]'::jsonb, 0, 'Hazard lights warn others that your vehicle is stationary in a hazardous position or broken down. They are not for normal driving in rain and do not legitimise illegal stopping.', null, 'Vehicle Controls', 'medium', '{"B"}', true, false, 'official_manual', 'approved', 13),
  ('VC-014', 'controls', 1, 'You are driving at night on bright (main) beam and a vehicle approaches from the opposite direction. What should you do?', '["Keep bright beam on to see better","Dip to low beam until it has passed","Switch your headlights off"]'::jsonb, 1, 'You must dip to low beam when meeting oncoming traffic so you do not dazzle the other driver, then return to main beam once it has passed. Keeping bright beam on dazzles; switching lights off is dangerous.', null, 'Vehicle Controls', 'medium', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 14),
  ('VC-015', 'controls', 1, 'When should you switch on your indicator before turning?', '["While you are turning","Only if another vehicle is close","In good time before you turn"]'::jsonb, 2, 'You should signal in good time before turning so other road users can react. Signalling during the turn is too late, and you must signal regardless of whether another vehicle is near.', null, 'Vehicle Controls', 'high', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 15),
  ('VC-016', 'controls', 3, 'On a motorcycle, when is it most important to have completed your braking?', '["Before entering the turn","While leaned over in the turn","After you have exited the turn"]'::jsonb, 0, 'You should set your speed and complete braking before entering a turn; braking hard (especially the front brake) while leaned over can cause a loss of control. Brakes are best applied upright before the turn.', null, 'Vehicle Controls', 'low', '{"A"}', true, false, 'generated_from_syllabus', 'approved', 16),
  ('VC-017', 'controls', 1, 'Which control disengages the engine from the gearbox so you can change gear?', '["The accelerator","The clutch","The handbrake"]'::jsonb, 1, 'The clutch disconnects the engine from the gearbox to allow a gear change. The accelerator controls speed and the handbrake holds the vehicle still.', null, 'Vehicle Controls', 'medium', '{"B"}', true, false, 'official_manual', 'approved', 17),
  ('VC-018', 'controls', 1, 'Before and while reversing, which controls help you see what is behind and beside you?', '["The hooter","The demister","The mirrors (and a direct look over your shoulder)"]'::jsonb, 2, 'The rear-view and side mirrors — supported by a direct look around — let you see behind and beside the vehicle before reversing. The hooter and demister do not provide vision.', null, 'Vehicle Controls', 'medium', '{"B"}', true, false, 'official_manual', 'approved', 18),
  ('VC-019', 'controls', 1, 'Which control actually changes the direction the vehicle travels?', '["The steering wheel","The indicator","The hooter"]'::jsonb, 0, 'The steering wheel changes the vehicle''s direction. The indicator only signals your intention to turn, and the hooter is a warning device.', null, 'Vehicle Controls', 'medium', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 19),
  ('VC-020', 'controls', 1, 'Which control would you use to warn another road user of danger to avoid a collision?', '["The indicator","The hooter","The wipers"]'::jsonb, 1, 'The hooter (horn) warns other road users of danger to avoid a collision. The indicator signals intention and the wipers clear the windscreen.', null, 'Vehicle Controls', 'medium', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 20),
  ('VC-021', 'controls', 1, 'When you press the foot brake, which lights warn the drivers behind you?', '["The headlights","The parking lights","The brake (stop) lights"]'::jsonb, 2, 'Pressing the foot brake lights the brake (stop) lights to warn following drivers you are slowing. Headlights and parking lights are not triggered by braking.', null, 'Vehicle Controls', 'medium', '{"A","B","C","EB"}', true, false, 'official_manual', 'approved', 21),
  ('VC-022', 'controls', 2, 'In a manual vehicle, why do you press the clutch just before coming to a stop?', '["To prevent the engine from stalling","To make the vehicle go faster","To activate the brake lights"]'::jsonb, 0, 'Pressing the clutch just before stopping disconnects the engine so it does not stall. It does not increase speed, and the brake lights are triggered by the brake, not the clutch.', null, 'Vehicle Controls', 'low', '{"B"}', true, false, 'official_manual', 'approved', 22),
  ('VC-023', 'controls', 2, 'You are stopped facing uphill and about to pull away. Which control holds the vehicle to prevent rolling back?', '["The accelerator","The handbrake","The demister"]'::jsonb, 1, 'The handbrake holds the vehicle on the hill until you have engine power to pull away, preventing roll-back. The accelerator and demister do not hold the vehicle.', null, 'Vehicle Controls', 'medium', '{"B"}', true, false, 'official_manual', 'approved', 23),
  ('VC-024', 'controls', 1, 'The rear window has misted up on the inside. Which control clears it?', '["The windscreen wipers","The hooter","The demister"]'::jsonb, 2, 'The demister clears condensation from the inside of the glass, including the rear window. The wipers clear the outside of the windscreen, and the hooter is a warning device.', null, 'Vehicle Controls', 'low', '{"B"}', true, false, 'official_manual', 'approved', 24),
  ('VC-025', 'controls', 1, 'When should the driver and passengers fasten their seatbelts?', '["Before the vehicle moves off","Only on the open road","Only if the trip is long"]'::jsonb, 0, 'Seatbelts must be fastened before the vehicle moves off and worn at all times. They are not optional for short trips or limited to the open road.', null, 'Vehicle Controls', 'high', '{"B"}', true, false, 'official_manual', 'approved', 25),
  ('VC-026', 'controls', 2, 'What is the safety purpose of a correctly set head restraint?', '["To make the seat more comfortable","To reduce whiplash neck injury in a rear-end collision","To support the seatbelt"]'::jsonb, 1, 'A head restraint limits rearward head movement to reduce whiplash in a rear-end crash. Comfort is incidental, and it does not support the seatbelt.', null, 'Vehicle Controls', 'low', '{"B"}', true, false, 'official_manual', 'approved', 26),
  ('VC-027', 'controls', 2, 'On a motorcycle, which hand or foot operates the front brake?', '["The left hand (a lever)","The left foot (a pedal)","The right hand (a lever)"]'::jsonb, 2, 'The motorcycle front brake is operated by the right-hand lever; the rear brake is the right-foot pedal and the clutch is the left-hand lever. Stopping uses front and rear brakes together.', null, 'Vehicle Controls', 'low', '{"A"}', true, false, 'official_manual', 'approved', 27),
  ('VC-028', 'controls', 1, 'Which motorcycle control increases engine speed?', '["The twist-grip throttle (right hand)","The clutch lever (left hand)","The front brake lever"]'::jsonb, 0, 'The right-hand twist-grip throttle increases engine speed on a motorcycle (the equivalent of a car''s accelerator). The clutch lever and front brake do not increase speed.', null, 'Vehicle Controls', 'low', '{"A"}', true, false, 'official_manual', 'approved', 28),
  ('VC-029', 'controls', 2, 'On a motorcycle, where are the clutch and the gear lever?', '["Clutch = right-hand lever; gear lever = right foot","Clutch = left-hand lever; gear lever = left foot","Both are hand-operated on the right"]'::jsonb, 1, 'On a motorcycle the clutch is the left-hand lever and the gear lever is operated by the left foot. The right side carries the throttle and front brake.', null, 'Vehicle Controls', 'low', '{"A"}', true, false, 'official_manual', 'approved', 29),
  ('VC-030', 'controls', 2, 'During hard emergency braking, what does ABS allow the driver to keep?', '["A shorter stopping distance on every surface","The need to pump the pedal","The ability to steer while braking"]'::jsonb, 2, 'ABS prevents wheel lock so you can keep steering while braking hard. It does not guarantee a shorter distance on every surface (it can lengthen it on gravel), and you should not pump the pedal.', null, 'Vehicle Controls', 'medium', '{"B"}', true, false, 'official_manual', 'approved', 30),
  ('VC-031', 'controls', 1, 'It starts to rain and your view through the windscreen is blurred. Which control do you use?', '["The windscreen wipers","The hazard lights","The hooter"]'::jsonb, 0, 'The windscreen wipers clear rain from the outside of the windscreen to restore your view. Hazard lights and the hooter do not improve forward visibility.', null, 'Vehicle Controls', 'medium', '{"B"}', true, false, 'official_manual', 'approved', 31),
  ('VC-032', 'controls', 2, 'How does changing gear in an automatic vehicle differ from a manual?', '["An automatic still needs the clutch for each gear change","An automatic has no clutch and selects gears itself","An automatic has no gears at all"]'::jsonb, 1, 'An automatic has no clutch control and selects gears itself; the driver uses the selector (P/R/N/D). It is not clutch-operated, and it does have gears.', null, 'Vehicle Controls', 'low', '{"B"}', true, false, 'official_manual', 'approved', 32)
on conflict (id) do nothing;
